#include "astc_gles.h"
#include "shader_source.h" // generated by CMake: gpuastc::kShaderSource

namespace gpuastc {

GLenum Encoder::internal_format(int block)
{
    return block == 6 ? 0x93B4u /* GL_COMPRESSED_RGBA_ASTC_6x6_KHR */
                      : 0x93B0u /* GL_COMPRESSED_RGBA_ASTC_4x4_KHR */;
}

Encoder::~Encoder() { destroy(); }

void Encoder::destroy()
{
    if (program_) {
        glDeleteProgram(program_);
        program_ = 0;
    }
}

bool Encoder::create(const Options& opt, std::string* log)
{
    destroy();
    opt_ = opt;

    std::string src = "#version 310 es\n";
    src += std::string("#define BLOCK_6X6 ") + (opt.block == 6 ? "1" : "0") + "\n";
    src += std::string("#define HAS_ALPHA ") + (opt.alpha ? "1" : "0") + "\n";
    src += std::string("#define IS_NORMALMAP ") + (opt.normal_map ? "1" : "0") + "\n";
    src += kShaderSource;

    GLuint sh = glCreateShader(GL_COMPUTE_SHADER);
    const char* p = src.c_str();
    glShaderSource(sh, 1, &p, nullptr);
    glCompileShader(sh);

    auto get_log = [&](bool is_prog, GLuint obj) {
        GLint len = 0;
        if (is_prog) glGetProgramiv(obj, GL_INFO_LOG_LENGTH, &len);
        else glGetShaderiv(obj, GL_INFO_LOG_LENGTH, &len);
        std::string s(len > 1 ? len : 1, '\0');
        if (is_prog) glGetProgramInfoLog(obj, len, nullptr, &s[0]);
        else glGetShaderInfoLog(obj, len, nullptr, &s[0]);
        return s;
    };

    GLint ok = 0;
    glGetShaderiv(sh, GL_COMPILE_STATUS, &ok);
    if (!ok) {
        if (log) *log = get_log(false, sh);
        glDeleteShader(sh);
        return false;
    }

    program_ = glCreateProgram();
    glAttachShader(program_, sh);
    glLinkProgram(program_);
    glDeleteShader(sh);

    glGetProgramiv(program_, GL_LINK_STATUS, &ok);
    if (!ok) {
        if (log) *log = get_log(true, program_);
        destroy();
        return false;
    }

    loc_tex_size_ = glGetUniformLocation(program_, "uTexSize");
    loc_blocks_ = glGetUniformLocation(program_, "uBlocks");
    loc_count_ = glGetUniformLocation(program_, "uN");
    return true;
}

bool Encoder::encode(GLuint tex, int width, int height, GLuint out_buffer)
{
    if (!program_ || width <= 0 || height <= 0)
        return false;

    const int bx = blocks(width, opt_.block);
    const int by = blocks(height, opt_.block);

    glBindBuffer(GL_SHADER_STORAGE_BUFFER, out_buffer);
    glBufferData(GL_SHADER_STORAGE_BUFFER, (GLsizeiptr)bx * by * 16, nullptr, GL_DYNAMIC_COPY);
    glBindBufferBase(GL_SHADER_STORAGE_BUFFER, 0, out_buffer);

    glActiveTexture(GL_TEXTURE0);
    glBindTexture(GL_TEXTURE_2D, tex);

    glUseProgram(program_);
    glUniform2i(loc_tex_size_, width, height);
    glUniform2i(loc_blocks_, bx, by);
    glUniform1i(loc_count_, opt_.block * opt_.block); // texels per block; keeps shader loops rolled
    glDispatchCompute((bx + 7) / 8, (by + 7) / 8, 1);

    glMemoryBarrier(GL_BUFFER_UPDATE_BARRIER_BIT | GL_PIXEL_BUFFER_BARRIER_BIT);
    return glGetError() == GL_NO_ERROR;
}

} // namespace gpuastc
